            ("a.b", false),
            ("a.fifo.fifo", false),
            ("a b", false),
            ("é", false),
        ];
        for (name, valid) in cases {
            assert_eq!(QueueName::parse(name).is_some(), valid, "{name:?}");
        }
    }
